import os
import requests

BASE_URL = os.getenv("SOCBENCH_API_BASE_URL", "https://api.socbench.example").rstrip("/")
session = requests.Session()
session.headers.update({"Accept": "application/json"})

def request(method, path, **kwargs):
    response = session.request(method, f"{BASE_URL}{path}", **kwargs)
    response.raise_for_status()
    if response.content:
        return response.json()
    return None

materials = request("GET", "/materials") or []
classified_materials = []

for material in materials:
    material_id = material.get("id")
    classification = request(
        "POST",
        "/materials/classify",
        json={"material": material},
    )
    classified_materials.append({
        "material": material,
        "classification": classification,
    })

    if material_id is not None and classification.get("requiresComplianceCheck"):
        compliance = request("GET", f"/materials/{material_id}/compliance")
        calculation_id = compliance.get("calculationId") if isinstance(compliance, dict) else None
        if calculation_id:
            compliance["calculationResult"] = request(
                "GET", f"/calculations/{calculation_id}/result"
            )
        classified_materials[-1]["compliance"] = compliance

inventory = request("GET", "/inventory/status")

request(
    "PATCH",
    "/logistics/route",
    json={
        "materials": classified_materials,
        "inventoryStatus": inventory,
        "routingInstructions": "Optimize shipment routes using recyclability classifications, compliance results, and available inventory.",
    },
)

request(
    "POST",
    "/equipment/maintenance-schedule",
