import os
import requests

BASE_URL = os.getenv("SOCBENCH_API_URL", "https://api.socbench.example").rstrip("/")
session = requests.Session()
session.headers.update({"Accept": "application/json", "Content-Type": "application/json"})

# Enable the hook for automatic cybersecurity threat alerts.
hook_response = session.post(
    f"{BASE_URL}/trigger-hook",
    json={"action": "enable", "purpose": "automatic_alerts_for_cybersecurity_threats"},
)
hook_response.raise_for_status()

# Retrieve threats and software inventory to identify associated vulnerabilities.
threats_response = session.get(f"{BASE_URL}/threats")
threats_response.raise_for_status()
threats = threats_response.json()

software_response = session.get(f"{BASE_URL}/software")
software_response.raise_for_status()
software_inventory = software_response.json()

# Match software records to threats using available names, IDs, and vulnerability references.
software_by_id = {
    str(item.get("id")): item
    for item in software_inventory
    if isinstance(item, dict) and item.get("id") is not None
}
software_by_name = {
    str(item.get("name", "")).casefold(): item
    for item in software_inventory
    if isinstance(item, dict) and item.get("name")
}

threats_list = threats if isinstance(threats, list) else threats.get("threats", [])
associations = []

for threat in threats_list:
    if not isinstance(threat, dict):
        continue

    associated_software = []
    for key in ("software_id", "affected_software_id"):
        software_id = threat.get(key)
        if software_id is not None and str(software_id) in software_by_id:
            associated_software.append(software_by_id[str(software_id)])

    for key in ("software", "software_name", "affected_software"):
        value = threat.get(key)
        if isinstance(value, str) and value.casefold() in software_by_name:
            associated_software.append(software_by_name[value.casefold()])
        elif isinstance(value, dict):
            associated_software.append(value)

    unique_software = {
        str(item.get("id", item.get("name", id(item)))): item
        for item in associated_software
    }
    associations.append(
        {
            "threat": threat,
            "software": list(unique_software.values()),
            "vulnerabilities": threat.get("vulnerabilities", []),
        }
    )

# Update alert rules to reflect threat conditions and remove rules explicitly marked unnecessary.
alerts_response = session.get(f"{BASE_URL}/alerts")
alerts_response.raise_for_status()
alerts_data = alerts_response.json()
alerts = alerts_data if isinstance(alerts_data, list) else alerts_data.get("alerts", [])

for alert in alerts:
    if not isinstance(alert, dict) or alert.get("id") is None:
        continue

    if alert.get("necessary") is False or alert.get("obsolete") is True:
        delete_response = session.delete(f"{BASE_URL}/alerts/{alert['id']}")
        delete_response.raise_for_status()
        continue

    conditions = alert.get("conditions", {})
    if not isinstance(conditions, dict):
        conditions = {"existing_conditions": conditions}

